                            t.HasCheckConstraint("ck_ivr_call_attempts_number_snapshot", "attempt_number >= 1 AND attempt_number <= max_attempts_snapshot AND max_attempts_snapshot BETWEEN 1 AND 10");

                            t.HasCheckConstraint("ck_ivr_call_attempts_result_status", "result_status IS NULL OR result_status IN ('IVR_CONFIRMED','IVR_CUSTOMER_CANCELLED','IVR_NO_ANSWER_ATTEMPT','IVR_NO_ANSWER_FINAL','IVR_CONFIRMATION_WINDOW_EXPIRED','IVR_INVALID_PHONE_FINAL','IVR_WRONG_INPUT','IVR_TECHNICAL_EXCEPTION','IVR_CAPACITY_EXCEPTION')");

                            t.HasCheckConstraint("ck_ivr_call_attempts_retry_nonnegative", "technical_retry_count >= 0");

                            t.HasCheckConstraint("ck_ivr_call_attempts_status", "status IN ('LEASED_PENDING_DISPATCH','DIALING','ACTIVE_CALL','PROVIDER_EVENT_PENDING_NORMALIZATION','NORMALIZED_ATTEMPT_COMPLETE','NORMALIZED_FINAL','NORMALIZED_TECHNICAL_RETRY','NORMALIZED_REVIEW_REQUIRED','TECHNICAL_RETRY_QUEUED','RECOVERY_REQUIRED')");

                            t.HasCheckConstraint("ck_ivr_call_attempts_technical_not_counted", "technical_exception_type IS NULL OR is_counted_customer_attempt IS FALSE");

                            t.HasCheckConstraint("ck_ivr_call_attempts_termination_complete", "(termination_requested_at IS NULL AND termination_requested_by IS NULL AND termination_reason IS NULL) OR (termination_requested_at IS NOT NULL AND termination_requested_by IS NOT NULL AND termination_reason IS NOT NULL)");

                            t.HasCheckConstraint("ck_ivr_call_attempts_voice_complete", "(voice_id IS NULL AND voice_region IS NULL AND voice_region_resolved IS NULL) OR (voice_id IS NOT NULL AND voice_region IS NOT NULL AND voice_region_resolved IS NOT NULL)");

                            t.HasCheckConstraint("ck_ivr_call_attempts_voice_region", "voice_region IS NULL OR voice_region IN ('North', 'Central', 'South')");
                        });
                });

